var WA = {
  canvas: document.getElementById('wa_canvas'),
  started: function() {
    var log = document.getElementById('wa_log');
    if (log) log.style.display = 'none';
    window.focus();
  }
};

var canvas = document.getElementById('wa_canvas');
if (canvas) {
  canvas.addEventListener('click', function() { window.focus(); });
  canvas.addEventListener('contextmenu', function(e) { e.preventDefault(); });
}

